import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';class AnnouncementsAdminPage extends StatefulWidget{const AnnouncementsAdminPage({super.key});@override State<AnnouncementsAdminPage> createState()=>_A();}class _A extends State<AnnouncementsAdminPage>{final title=TextEditingController(),body=TextEditingController();Future<void> send()async{if(title.text.trim().isEmpty)return;await FirebaseFirestore.instance.collection('announcements').add({'title':title.text.trim(),'body':body.text.trim(),'active':true,'createdAt':FieldValue.serverTimestamp()});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Pengumuman')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Judul')),TextField(controller:body,maxLines:4,decoration:const InputDecoration(labelText:'Isi')),const SizedBox(height:16),FilledButton.icon(onPressed:send,icon:const Icon(Icons.send),label:const Text('Kirim'))])));}